// Regenerates the Prisma client in src/generated/prisma only when it is
// missing or stale (older than prisma/schema.prisma, or generated by another
// @prisma/client version). Used as a pre-step for dev, test and tooling
// scripts so a fresh `npm ci` checkout works without an install hook; the
// published package ships the compiled client and never runs Prisma.
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const schema = join(root, 'prisma', 'schema.prisma');
const marker = join(root, 'src', 'generated', 'prisma', 'internal', 'class.ts');

function installedClientVersion() {
  try {
    return JSON.parse(readFileSync(join(root, 'node_modules', '@prisma', 'client', 'package.json'), 'utf8')).version;
  } catch {
    return null;
  }
}

function isCurrent() {
  if (!existsSync(marker)) return false;
  if (statSync(marker).mtimeMs < statSync(schema).mtimeMs) return false;
  const generated = /"clientVersion": "([^"]+)"/u.exec(readFileSync(marker, 'utf8'))?.[1];
  return generated === installedClientVersion();
}

if (!isCurrent()) {
  // Keep stdout clean for commands whose output is parsed (for example --json).
  const result = spawnSync('npm', ['run', '--silent', 'db:generate'], { cwd: root, stdio: ['ignore', 2, 2] });
  process.exit(result.status ?? 1);
}
